const body = $json.body || {};
const headers = $json.headers || {};
const expectedSecret = 'O2LwUFK2HvTDhG53';
const senderPhoneNumberId = '1203164092890708';
const receivedSecret = String(headers['x-lms-whatsapp-secret'] || headers['X-Lms-Whatsapp-Secret'] || '').trim();

if (expectedSecret && receivedSecret !== expectedSecret) {
  throw new Error('Invalid LMS WhatsApp forwarding secret');
}

const normalizeWhatsAppNumber = (value) => {
  const digits = String(value || '').replace(/\D/g, '');
  return digits.length === 10 ? `91${digits}` : digits;
};

const rawRecipients = Array.isArray(body.recipients) && body.recipients.length
  ? body.recipients
  : body.to
    ? [body.to]
    : [];

const recipients = [...new Set(rawRecipients.map(normalizeWhatsAppNumber).filter(Boolean))];
if (!recipients.length) throw new Error('No WhatsApp recipients provided');

const bodyComponent = Array.isArray(body.components)
  ? body.components.find((component) => String(component?.type || '').toLowerCase() === 'body')
  : null;

const componentParameters = Array.isArray(bodyComponent?.parameters)
  ? bodyComponent.parameters
      .map((parameter) => String(parameter?.text ?? parameter?.value ?? '').slice(0, 1024))
      .filter(Boolean)
  : [];

const rawBodyParameters = Array.isArray(body.bodyParameters)
  ? body.bodyParameters
  : Array.isArray(body.templateVariables)
    ? body.templateVariables
    : componentParameters;

const bodyParameters = rawBodyParameters
  .map((value) => String(value || '').trim().slice(0, 1024))
  .filter(Boolean);

const type = String(body.type || 'template').trim().toLowerCase() === 'text' ? 'text' : 'template';
const textBody = String(body.message || body.text || '').trim().slice(0, 4096);
if (type === 'text' && !textBody) throw new Error('Missing text message body');

const templateName = String(body.templateName || body.template_name || '').trim();
const language = String(body.language || body.language_code || 'en_US').trim();
if (type === 'template' && !templateName) throw new Error('No WhatsApp template name provided');

return recipients.map((recipientPhoneNumber) => {
  const component = bodyParameters.length
    ? [
        {
          type: 'body',
          bodyParameters: {
            parameter: bodyParameters.map((text) => ({ type: 'text', text })),
          },
        },
      ]
    : [];

  return {
    json: {
      type,
      phoneNumberId: senderPhoneNumberId,
      recipientPhoneNumber,
      textBody,
      template: templateName,
      templateName,
      language,
      bodyParameters,
      components: component,
      graphRequestBody: {
        messaging_product: "whatsapp",
        recipient_type: "individual",
        to: recipientPhoneNumber,
        type: "template",
        template: {
          name: templateName,
          language: { code: language },
          ...(component.length ? { components: component.map((entry) => ({
            type: entry.type,
            parameters: entry.bodyParameters.parameter.map((parameter) => ({ type: parameter.type, text: parameter.text })),
          })) } : {}),
        },
      },
      metadata: body.metadata || {},
      debug: {
        sender: 'n8n_whatsapp_node',
        phoneNumberId: senderPhoneNumberId,
        recipientPhoneNumber,
        messageType: type,
        templateName,
        templateLanguage: language,
        bodyParameterCount: bodyParameters.length,
      },
    },
  };
});

const sentItems = $input.all();
const requestItems = $items('Prepare LMS Send Request');

const errorText = (value) => {
  if (!value) return '';
  if (typeof value === 'string') return value;
  return String(value.message || value.error_user_msg || value.error || JSON.stringify(value));
};

const results = sentItems.map((item, index) => {
  const response = item.json || {};
  const request = requestItems[index]?.json || {};
  const itemError = item.error || {};
  const nestedError = response.body?.error || response.data?.error || response.error || null;
  const message = response.messages?.[0] || response.body?.messages?.[0] || response.data?.messages?.[0] || null;
  const error = errorText(nestedError || itemError?.message || response.message || response.errorDescription);
  const ok = Boolean(message?.id || response.messaging_product || response.metaMessageId) && !error;

  return {
    phoneNumber: request.recipientPhoneNumber || response.to || '',
    to: request.recipientPhoneNumber || response.to || '',
    ok,
    status: ok ? (message?.message_status || 'accepted') : 'failed',
    metaMessageId: message?.id || response.metaMessageId || '',
    templateName: request.templateName || '',
    messageType: request.type || 'template',
    error: ok ? '' : error || 'WhatsApp send failed in n8n.',
    metaError: ok ? null : nestedError,
    debug: {
      ...(request.debug || {}),
      rawResponse: response,
      itemError,
    },
  };
});

return [{ json: { ok: results.length > 0 && results.every((result) => result.ok), results } }];

const input = $json || {};
const source = input.body && typeof input.body === 'object' ? input.body : input;

if (Array.isArray(source.entry)) {
  return [{ json: source }];
}

const messages = Array.isArray(source.messages)
  ? source.messages
  : source.from && (source.id || source.waMessageId || source.providerMessageId)
    ? [source]
    : [];

const statuses = Array.isArray(source.statuses)
  ? source.statuses
  : source.status && source.id
    ? [source]
    : [];

if (!messages.length && !statuses.length) {
  return [{ json: source }];
}

const normalizeTimestamp = (value) => {
  if (value === undefined || value === null || value === '') return new Date().toISOString();
  const raw = String(value).trim();
  if (/^\d+$/.test(raw)) {
    const numeric = Number(raw);
    return new Date(numeric < 10000000000 ? numeric * 1000 : numeric).toISOString();
  }
  const parsed = new Date(raw);
  return Number.isNaN(parsed.getTime()) ? new Date().toISOString() : parsed.toISOString();
};

return [{
  json: {
    messaging_product: source.messaging_product || 'whatsapp',
    metadata: source.metadata || {},
    contacts: source.contacts || [],
    messages: messages.map((message) => ({
      ...message,
      id: String(message.id || message.waMessageId || message.providerMessageId || ''),
      from: String(message.from || message.waId || ''),
      type: message.type || 'text',
      timestamp: normalizeTimestamp(message.timestamp),
      text: typeof message.text === 'string' ? { body: message.text } : message.text,
    })),
    statuses,
  },
}];
